using UnityEngine;using LighthouseKeepers.Lobby;
namespace LighthouseKeepers.WatchDemo {
 public sealed partial class WatchDemoController {
  int LocalKeeper=>(coop as ICoopKeeperLocations)?.LocalActor??0;
  public CrewDuty CurrentDuty=>(coop as ICoopKeeperDuties)?.Duty(LocalKeeper)??CrewDuties.Preference;
  public KeeperStep CurrentInstruction=>GetComponent<ArrivalEquipment>() is ArrivalEquipment kit && kit.Step!=KeeperStep.None?kit.Step:state?.Director?.ForActor(LocalKeeper)??KeeperStep.None;
  public KeeperStep PartnerInstruction=>state?.Director?.Partner(LocalKeeper)??KeeperStep.None;
  public int InstructionFloor(KeeperStep step){if(step==KeeperStep.HelpPartner){var helper=GetComponent<CrewCompanion>();return helper&&helper.Active?ObjectiveHud.KeeperFloor(helper.Position):-1;}return ObjectiveDirector.Floor(step);}
  public void DrownedViewers(out int a,out Vector3 p,out Vector3 f,out int b,out Vector3 q,out Vector3 g){a=b=0;p=q=head.position;f=g=head.forward;if(coop is ICoopKeeperLocations locations){locations.Locations(out a,out p,out b,out q);if(a==0){p=head.position;f=head.forward;}if(coop is ICoopKeeperViews views){if(a!=0)views.View(a,out f);if(b!=0)views.View(b,out g);}}}
  void InitializeDirector(){if(state.Director==null)return;state.Director.StationPosition=StationPosition;state.Director.DutyForActor=actor=>(coop as ICoopKeeperDuties)?.Duty(actor)??CrewDuties.Preference;state.Director.CompanionStep=()=>GetComponent<CrewCompanion>()?.WorkingStep??KeeperStep.None;UpdateDirector();DirectorPresentation.Create(this,head);StationObjectiveGuidance.Create(this);}
  Vector3 StationPosition(string id)=>id=="STN_PRESSURE_VALVE"&&pressureValve?pressureValve.transform.position:id==WatchState.PipeStation?pipeRepair.ActivePosition:id==WatchState.GeneratorStation?generator.transform.position+Vector3.up:id==WatchState.RadioStation?radio.transform.position+Vector3.up:beaconStation?beaconStation.transform.position+Vector3.up:head.position;
  void UpdateDirector(){if(state==null||state.ReadOnly)return;int a=0,b=0;var p=head.position;var q=p;if(coop is ICoopKeeperLocations locations)locations.Locations(out a,out p,out b,out q);if(a==0)p=head.position;if(state.ScriptedPartner&&LocalWrenchHeld)state.PipeWorkerActor=a>0?a:1;state.Director?.Tick(Time.time,a,p,b,q,WrenchHeld);if(!sleeping)state.ObserveKeepers(Time.deltaTime,a,p,b,q);}
  void DirectorBoard(){boardText.Clear();boardText.Append(KeeperStrings.Get(state.Survival?"survival.board.goal":"board.goal")).Append('\n').AppendFormat(KeeperStrings.Get(state.Survival?"survival.board.day":"board.night"),state.Day).Append(state.Ships!=null?"\n":LighthouseKeepers.Core.PlayerStrings.Get("legacy.WatchDemoController.Director.1"));foreach(var task in state.Definition.tasks)boardText.Append(state.IsDone(task.stationId)?"✓ ":"○ ").Append(KeeperStrings.Get("job."+task.stationId)).Append('\n');if(state.Ships!=null){boardText.Append(KeeperStrings.Get("board.ships")).Append(' ');for(int i=0;i<state.Ships.Count;i++)boardText.Append(state.Ships.Passed(i)?"✓ ":state.Ships.WreckIndex==i?"✗ ":"○ ");boardText.Append('\n');}boardText.Append(state.Complete?"○ ":"  ").Append(KeeperStrings.Get("job.BED"));if(crewBeds>0&&!sleeping)boardText.Append(" (").Append(crewBeds).Append('/').Append(crewKeepers).Append(')');boardText.Append(state.Ships!=null?"\n":LighthouseKeepers.Core.PlayerStrings.Get("legacy.WatchDemoController.Director.1")).Append(KeeperStrings.Get(state.Survival?"survival.board.loop":state.Campaign?"board.loop.five":"board.loop")).Append('\n').Append(KeeperStrings.Get(state.SurvivalPractice?"survival.board.practice":state.Survival?"survival.board.loss":state.Ships!=null?"board.shipLoss":"board.loss"));if(!string.IsNullOrEmpty(crewNotice))boardText.Append('\n').Append(crewNotice);board.text=boardText.ToString();}
 }
}
